#!/bin/sh
# axRange cast twin -- real protocol servers for node 'monitoring-collector-10-20-194-core'.
# GENERATED by aximprint (`synth/services.py`); do not hand-edit -- a re-cast
# overwrites it, and an edit that lives only in the installed file is an edit the
# next re-cast silently discards.
#
# Declared listen set (from the OBSERVED listen census, never the persona dial set --
# `axrange/docs/WORK_ORDER_protocol_faithful_services.md` §2):
#   9997/tcp
# Origin: node group 'monitoring-collector-10-20-194-core'
#
#   9997/tcp         -> echo responder (evidence class: compiler)
# Delivered as an `install: [{script: ...}]` action, so it runs through `run-script`
# (OP-APP-030) IN-GUEST as root, honouring this shebang.
set -eu
umask 022
mkdir -p /usr/local/lib/axr /var/log/axrange

# Install only what is MISSING, and refresh the index first. A cloned guest's apt index is
# stale by construction -- axRange fixed exactly this on its own `provision-app` path on
# 2026-08-14, and a `pkg:` action having already run is the common case here, which is why the
# whole body is skipped when nothing is missing.
axr_pkg() {
    _missing=""
    for _p in "$@"; do
        if ! dpkg-query -W -f='${Status}' "$_p" 2>/dev/null \
                | grep -q '^install ok installed$'; then
            _missing="$_missing $_p"
        fi
    done
    if [ -n "$_missing" ]; then
        DEBIAN_FRONTEND=noninteractive apt-get update -qq
        # shellcheck disable=SC2086
        DEBIAN_FRONTEND=noninteractive apt-get install -y -qq \
            --no-install-recommends $_missing
    fi
}

# A Debian package's unit name is not stable across releases (bind9 -> named, chrony ->
# chronyd on RH-derived images). Resolve it from what is actually installed rather than
# guessing at render time.
axr_unit_name() {
    for _u in "$@"; do
        if systemctl list-unit-files "$_u.service" >/dev/null 2>&1 \
                && systemctl list-unit-files "$_u.service" 2>/dev/null | grep -q "^$_u\.service"; then
            echo "$_u"; return 0
        fi
    done
    echo "$1"
}

# FAIL LOUD. A server that did not start is indistinguishable downstream from the no-listener
# defect this whole file replaces, and `systemctl is-active` is the only thing that can tell
# them apart (axRange LES-079/LES-086; never `nohup ... &`, which the guest-agent session
# reaps).
axr_unit() {
    systemctl enable "$1" >/dev/null 2>&1 || true
    systemctl restart "$1"
    sleep 1
    if ! systemctl is-active --quiet "$1"; then
        systemctl status --no-pager --full "$1" >&2 || true
        echo "axr-serve: unit '$1' did not start" >&2
        exit 1
    fi
}

axr_assert_unit() {
    for _u in "$@"; do
        if systemctl is-active --quiet "$_u"; then return 0; fi
    done
    echo "axr-serve: none of the units '$*' is active" >&2
    exit 1
}

axr_self_ip() { ip -4 -o addr show scope global | awk '{split($4,a,"/"); print a[1]; exit}'; }
axr_gateway() { ip -4 route show default | awk '{print $3; exit}'; }

# --- echo responder (evidence class: compiler) ------------------------------
# serves: 9997/tcp
# No real server in `SERVER_RECIPES` covers these ports. They are echoed rather than left
# silent because an unserved port draws an ICMP unreachable that Zeek scores as a FABRICATED
# reverse local edge -- silence manufactures evidence exactly as filler does (D8(a)).
cat > /usr/local/lib/axr/responder.py <<'AXR_RESPONDER_EOF'
import errno, socket, sys, threading

def _serve_tcp(s):
    while True:
        try:
            conn, _ = s.accept()
        except OSError:
            continue
        threading.Thread(target=_echo, args=(conn,), daemon=True).start()

def _echo(conn):
    # Echo rather than drain: a persona measuring bytes needs the far side to actually
    # move them back, and an echo keeps the conversation shaped like a real exchange.
    try:
        while True:
            data = conn.recv(65536)
            if not data:
                break
            conn.sendall(data)
    except OSError:
        pass
    finally:
        try:
            conn.close()
        except OSError:
            pass

def _serve_udp(s):
    while True:
        try:
            data, addr = s.recvfrom(65536)
            s.sendto(data, addr)
        except OSError:
            continue

# Bind EVERY socket up front, in the main thread, and die loudly if any one fails.
# Binding inside the per-port thread hides a partial failure completely: the thread
# raises, the process keeps running because its siblings are healthy, and
# `systemctl is-active` still says "active" -- measured on dns-resolver-10-80-64,
# where the port-53 thread crashed on EADDRINUSE (systemd-resolved owns 53) while the
# unit reported healthy and the op passed. A responder serving SOME of its ports is
# the silent-partial-success case, which is worse than a hard failure because the
# fingerprint then blames the personas.
_socks = []
for spec in sys.argv[1:]:
    p, _, proto = spec.partition("/")
    port = int(p)
    try:
        if proto == "udp":
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(("0.0.0.0", port))
        else:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(("0.0.0.0", port)); s.listen(128)
    except OSError as exc:
        # Already served by a REAL daemon is a success, not a failure: a dns-resolver node
        # installs bind9 and `named` owns :53 (measured on dev45 -- the responder was
        # competing with the very service that makes the role real). The point is that
        # SOMETHING answers, so a port another process holds needs no responder. Anything
        # else is a genuine failure and still exits non-zero.
        if exc.errno == errno.EADDRINUSE:
            sys.stderr.write("axr-responder: %s already served by another process, "
                             "skipping\n" % spec)
            continue
        sys.stderr.write("axr-responder: cannot bind %s: %s\n" % (spec, exc))
        raise SystemExit(1)
    _socks.append((s, proto))

for s, proto in _socks:
    target = _serve_udp if proto == "udp" else _serve_tcp
    threading.Thread(target=target, args=(s,), daemon=True).start()

threading.Event().wait()
AXR_RESPONDER_EOF
systemctl stop axr-responder.service 2>/dev/null || true
systemd-run --unit=axr-responder --collect \
    /usr/bin/python3 /usr/local/lib/axr/responder.py 9997/tcp
sleep 1
systemctl is-active --quiet axr-responder.service

echo "axr-serve: monitoring-collector-10-20-194-core ready (9997/tcp)"
